import { YIELD_BENCHMARK_SCORE_TTL_SEC } from "./status-thresholds";
import { DAY_SECONDS } from "./time-constants";
import type { YieldBenchmarkKey, YieldBenchmarkSelectionMode } from "../types/yield";

export type YieldBenchmarkFreshness = "healthy" | "degraded" | "stale";

// Benchmark timestamps are generated by external publishers and may lead the
// worker clock slightly; larger leads are unusable rather than "age zero".
const YIELD_BENCHMARK_MAX_FUTURE_SKEW_SEC = 5 * 60;

/**
 * Per-key bound on the age of a benchmark's own observation (`recordDate`).
 * A fetch that just succeeded says nothing about the data it carried: a frozen
 * or rewound upstream keeps returning an old CSV, and the fetch-age TTL alone
 * would stamp it as current market data forever. Bounds follow each series'
 * real publication calendar, not one size: daily/overnight series get five
 * days (a long weekend plus one failed run), keys whose calendars have
 * multi-day holiday clusters carry more (see per-key comments), and CAD is
 * the Bank of Canada's monthly announced Bank rate.
 */
export const YIELD_BENCHMARK_RECORD_MAX_AGE_SEC: Record<YieldBenchmarkKey, number> = {
  USD: 5 * DAY_SECONDS,
  USD_EFFR: 5 * DAY_SECONDS,
  EUR: 5 * DAY_SECONDS,
  // SAR3MC publishes T+1 and the Good Friday + Easter Monday cluster lands the
  // newest print exactly 5d old, tripping the daily bound every year.
  CHF: 7 * DAY_SECONDS,
  GBP: 5 * DAY_SECONDS,
  JPY: 5 * DAY_SECONDS,
  MXN: 5 * DAY_SECONDS,
  BRL: 5 * DAY_SECONDS,
  AUD: 5 * DAY_SECONDS,
  CAD: 45 * DAY_SECONDS,
  // CBR key-rate prints sit ~9-10 days old across every Jan 1-8 holiday cluster.
  RUB: 12 * DAY_SECONDS,
  // TCMB Kurban/Bayram holiday clusters can leave the newest print past 5d.
  TRY: 10 * DAY_SECONDS,
  SGD: 5 * DAY_SECONDS,
};

/**
 * Per-key bound on a newly fetched market rate's relative move against the last
 * published market observation. The provider range guard only rejects values
 * outside a broad band (-10..20, 100 for TRY/RUB), so a publisher that changes
 * units or column meaning while staying in range (4.3 -> 0.43) would otherwise
 * publish as a current benchmark. High-rate keys (policy rates that can move by
 * whole points) get a wider band; the unit-scale window below still catches a
 * silent 10x/0.1x rescale for every key.
 */
const YIELD_BENCHMARK_MAX_RELATIVE_CHANGE: Record<YieldBenchmarkKey, number> = {
  USD: 0.3,
  USD_EFFR: 0.3,
  EUR: 0.3,
  CHF: 0.3,
  GBP: 0.3,
  JPY: 0.3,
  CAD: 0.3,
  AUD: 0.3,
  SGD: 0.3,
  MXN: 1,
  BRL: 1,
  RUB: 1,
  TRY: 1,
};

/** Ratios only a unit change produces, whatever the key's own band. */
const UNIT_SCALE_RATIO_MIN = 0.05;
const UNIT_SCALE_RATIO_MAX = 0.2;
const UNIT_SCALE_RATIO_INVERSE_MIN = 5;
const UNIT_SCALE_RATIO_INVERSE_MAX = 20;
/**
 * Absolute move (percentage points) below which no relative band applies:
 * near-zero policy benchmarks (CHF SAR3MC, EUR €STR) produce huge ratios from
 * economically tiny moves.
 */
const RATE_ABSOLUTE_MOVE_FLOOR = 0.25;

/**
 * Whether a freshly parsed market rate may replace the published benchmark.
 * Without a prior market observation there is no local baseline; the provider's
 * own range guard remains the only value check. A rejected rate keeps the
 * previous retained value and names `<key>-rate-out-of-band` in run metadata.
 */
export function isYieldBenchmarkRatePlausible(
  key: YieldBenchmarkKey,
  rate: number,
  previousMarketRate: number | null | undefined,
): boolean {
  // Policy benchmarks may legitimately publish zero or negative observations.
  if (!Number.isFinite(rate)) return false;
  if (previousMarketRate == null || !Number.isFinite(previousMarketRate) || previousMarketRate === 0) return true;
  if (Math.abs(rate - previousMarketRate) <= RATE_ABSOLUTE_MOVE_FLOOR) return true;
  const ratio = rate / previousMarketRate;
  if ((ratio >= UNIT_SCALE_RATIO_MIN && ratio <= UNIT_SCALE_RATIO_MAX)
    || (ratio >= UNIT_SCALE_RATIO_INVERSE_MIN && ratio <= UNIT_SCALE_RATIO_INVERSE_MAX)) {
    return false;
  }
  return Math.abs(ratio - 1) <= YIELD_BENCHMARK_MAX_RELATIVE_CHANGE[key];
}

/**
 * Age of a benchmark's own observation at `nowSec`. `null` when the entry
 * carries no parseable observation date. Small clock skew is tolerated, but a
 * farther-future observation returns a negative age so callers fail closed.
 */
export function benchmarkRecordAgeSeconds(
  recordDate: string | null | undefined,
  nowSec: number,
): number | null {
  if (!recordDate) return null;
  const recordTimestampMs = Date.parse(`${recordDate}T00:00:00Z`);
  if (!Number.isFinite(recordTimestampMs)) return null;
  const ageSec = nowSec - Math.floor(recordTimestampMs / 1000);
  return ageSec < 0 && ageSec >= -YIELD_BENCHMARK_MAX_FUTURE_SKEW_SEC ? 0 : ageSec;
}

/**
 * Classify a registry entry from its own evidence: the hard 48h fetch-age TTL,
 * plus — when the caller supplies the key's observation bound — the age of the
 * observation the fetch carried. Both are `max`-combined. Missing, unparseable,
 * or farther-future bounded observations are stale. Shared so the API read path
 * and the cron write path apply one rule without crossing the worker api/cron
 * import boundary.
 */
export function classifyYieldBenchmarkFreshness(meta: {
  ageSeconds: number | null;
  isFallback: boolean;
  fallbackMode: string | null;
}, options?: {
  selectionMode?: YieldBenchmarkSelectionMode | null;
  /** The benchmark's own observation date, as published on the registry entry. */
  recordDate?: string | null;
  /** Per-key bound, normally `YIELD_BENCHMARK_RECORD_MAX_AGE_SEC[key]`. */
  maxRecordAgeSec?: number | null;
  /** Assessment clock; defaults to the current time. */
  nowSec?: number;
}): YieldBenchmarkFreshness {
  if (
    meta.ageSeconds == null ||
    !Number.isFinite(meta.ageSeconds) ||
    meta.ageSeconds < 0 ||
    meta.ageSeconds > YIELD_BENCHMARK_SCORE_TTL_SEC
  ) {
    return "stale";
  }
  const maxRecordAgeSec = options?.maxRecordAgeSec;
  if (maxRecordAgeSec != null && Number.isFinite(maxRecordAgeSec)) {
    const recordAgeSec = benchmarkRecordAgeSeconds(options?.recordDate, options?.nowSec ?? Math.floor(Date.now() / 1000));
    if (recordAgeSec == null || recordAgeSec < 0 || recordAgeSec > maxRecordAgeSec) {
      return "stale";
    }
  }
  if (
    meta.isFallback ||
    meta.fallbackMode != null ||
    options?.selectionMode === "fallback-usd"
  ) {
    return "degraded";
  }
  return "healthy";
}
